def add_limit(o):
    fills = []
    opp = book.asks if o.side == BUY else book.bids
    crosses = (lambda px: px <= o.price) if o.side == BUY else (lambda px: px >= o.price)
    while o.qty > 0 and opp.best() and crosses(opp.best().price):
        lvl = opp.best()
        while o.qty > 0 and lvl.head:
            m = lvl.head
            if m.member == o.member and stp_enabled:
                cancel_resting(m); continue        // self-trade prevention
            q = min(o.qty, m.qty)
            fills.append(Trade(px=lvl.price, qty=q, taker=o.id, maker=m.id))
            o.qty -= q; m.qty -= q
            if m.qty == 0: lvl.pop_head(); index.remove(m.id)
        if lvl.empty(): opp.remove_level(lvl)
    if o.qty > 0 and o.tif == DAY:
        same = book.side(o.side).level(o.price, create=True)
        same.append(o); index[o.id] = o
    return fills

def auction_price(bids, asks, ref):
    best = None
    for p in candidate_prices(bids, asks):
        demand = sum(q for px, q in bids if px >= p)
        supply = sum(q for px, q in asks if px <= p)
        vol, imb = min(demand, supply), abs(demand - supply)
        key = (vol, -imb, -abs(p - ref))
        if best is None or key > best[0]: best = (key, p)
    return best[1]
